<?php
$search=mb_substr(trim((string)($_GET['q']??'')),0,150);$filter=(string)($_GET['sector']??'');
$params=[$u['id']];$where='d.user_id=?';
if($search!=='') { $where.=' AND d.title LIKE ?';$params[]='%'.$search.'%'; }
if(in_array($filter,sectors(),true)) { $where.=' AND d.sector=?';$params[]=$filter; }
$count=(int)query('SELECT COUNT(*) FROM documents d WHERE '.$where,$params)->fetchColumn();
$number=max(1,min(100000,(int)($_GET['p']??1)));$offset=($number-1)*15;
$recent=query('SELECT a.id,a.score,a.created_at,d.title,d.sector FROM analyses a JOIN documents d ON d.id=a.document_id WHERE '.$where.' ORDER BY a.id DESC LIMIT 15 OFFSET '.$offset,$params)->fetchAll();
?>
<div class="page-heading"><div><span class="eyebrow">ÇALIŞMALARINIZ TEK BİR YERDE</span><h1>Analiz geçmişi<span class="heading-dot">.</span></h1><p>Önceki bulgularınızı inceleyin, metinler arasındaki farkları görün.</p></div><a class="button" href="<?= url('analyze') ?>#new-analysis"><?= icon('plus') ?> Yeni analiz</a></div>
<section class="panel"><form class="filter-form" method="get"><input type="hidden" name="page" value="history"><label class="search-field"><span class="visually-hidden">Belge adı ara</span><?= icon('search') ?><input name="q" value="<?= e($search) ?>" placeholder="Belge adıyla ara…" maxlength="150"></label><label><span class="visually-hidden">Sektör</span><select name="sector"><option value="">Tüm sektörler</option><?php foreach(sectors() as $s): ?><option <?= $filter===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach ?></select></label><button class="button secondary">Filtrele</button><?php if($search||$filter): ?><a class="text-link" href="<?= url('history') ?>">Temizle</a><?php endif ?></form>
<?php if($recent): require __DIR__.'/table.php';else: ?><div class="empty"><?= icon('history') ?><h2>Henüz bir kayıt bulunamadı.</h2><p>Arama filtrelerini değiştirin veya yeni bir metin analiz edin.</p></div><?php endif ?>
<div class="pagination"><span><?= $count ?> analiz · Sayfa <?= $number ?></span><div><?php if($number>1): ?><a class="button secondary small" href="<?= url('history',['q'=>$search,'sector'=>$filter,'p'=>$number-1]) ?>">Önceki</a><?php endif ?><?php if($offset+15<$count): ?><a class="button secondary small" href="<?= url('history',['q'=>$search,'sector'=>$filter,'p'=>$number+1]) ?>">Sonraki</a><?php endif ?></div></div></section>
<?php $choices=query('SELECT a.id,d.title FROM analyses a JOIN documents d ON d.id=a.document_id WHERE d.user_id=? ORDER BY a.id DESC LIMIT 100',[$u['id']])->fetchAll();if(count($choices)>=2): ?>
<section class="panel compare-panel"><div class="panel-heading"><div><span class="eyebrow">YAN YANA İNCELEYİN</span><h2>İki analizi karşılaştırın</h2><p>Skor farklarını ve her kriterin bulgu durumunu görün.</p></div><?= icon('chart') ?></div><form method="get" class="compare-form"><input type="hidden" name="page" value="history"><?php foreach(['left'=>'İlk analiz','right'=>'İkinci analiz'] as $key=>$label): ?><label><?= $label ?><select name="<?= $key ?>" required><option value="">Analiz seçin</option><?php foreach($choices as $choice): ?><option value="<?= (int)$choice['id'] ?>" <?= (int)($_GET[$key]??0)===(int)$choice['id']?'selected':'' ?>>#<?= (int)$choice['id'] ?> · <?= e($choice['title']) ?></option><?php endforeach ?></select></label><?php endforeach ?><button class="button secondary">Karşılaştır</button></form>
<?php if(!empty($_GET['left'])&&!empty($_GET['right'])):
$left=findAnalysis((int)$_GET['left'],$u);$right=findAnalysis((int)$_GET['right'],$u);
if($left&&$right&&(int)$left['user_id']===(int)$u['id']&&(int)$right['user_id']===(int)$u['id']): ?>
<div class="table-wrap"><table><thead><tr><th>Kriter</th><th><?= e($left['title']) ?></th><th><?= e($right['title']) ?></th></tr></thead><tbody><tr><th>Kapsam skoru</th><td><?= $left['score'] ?>/100</td><td><?= $right['score'] ?>/100 <span class="muted">(<?= sprintf('%+d',(int)$right['score']-(int)$left['score']) ?> puan)</span></td></tr><?php foreach(Analyzer::criteria() as $key=>$c): ?><tr><th><?= e($c['title']) ?></th><td><?= badge($left['result']['criteria'][$key]['status']) ?></td><td><?= badge($right['result']['criteria'][$key]['status']) ?></td></tr><?php endforeach ?></tbody></table></div>
<?php else: ?><p class="alert error" role="alert">Karşılaştırmak istediğiniz analizler bulunamadı.</p><?php endif;endif ?></section><?php endif ?>
